// The stack as COBOL: frames in a source generated by Cobalto are shown at
// the .cblt or at the original program, frames in generated C are marked,
// and a step is repeated until the top frame reaches another COBOL
// statement.

import * as path from 'path';
import { Channel } from './channel';
import { programFromFunction } from './cobol-map';
import { DapEvent, DapRequest, DapResponse } from './protocol';
import { Session } from './session';

interface Location {
  path?: string;
  line?: number;
  isCobol: boolean;
}

interface FrameInfo extends Location {
  id: number;
  program?: string;
}

interface Stepping {
  threadId: number;
  command: 'next' | 'stepIn';
  granularity?: unknown;
  start?: Location;
  count: number;
}

const COBOL_EXT = /\.(cbl|cob|cobol|cblt|cpy|copy)$/i;

export function isCobolPath(p: string | undefined): boolean {
  return !!p && COBOL_EXT.test(p);
}

export class Stack {
  /** frames seen since the last stop, by id */
  readonly frames = new Map<number, FrameInfo>();
  /** variablesReference of a scope -> frame it belongs to */
  readonly scopeFrame = new Map<number, number>();
  private stepping?: Stepping;

  constructor(private readonly ch: Channel, private readonly session: Session) {}

  /** A new stop: the ids of the previous one are no longer valid. */
  clear(): void {
    this.frames.clear();
    this.scopeFrame.clear();
  }

  /** Whether a "step" stop on that thread is part of a step in progress. */
  stepsOn(threadId: number | undefined): boolean {
    return !!this.stepping && threadId === this.stepping.threadId;
  }

  /** True between the internal steps of one COBOL statement. */
  get midStep(): boolean {
    return !!this.stepping && this.stepping.count > 0;
  }

  stopStepping(): void {
    this.stepping = undefined;
  }

  private frameInfo(frame: Record<string, unknown>): FrameInfo {
    const source = frame.source as { path?: string; name?: string } | undefined;
    const p = source?.path ? path.resolve(source.path) : undefined;
    const line = typeof frame.line === 'number' ? frame.line : undefined;
    const info: FrameInfo = {
      id: frame.id as number,
      program: programFromFunction(frame.name as string) ?? (p ? path.basename(p).replace(/\..*$/, '').toUpperCase() : undefined),
      path: p,
      line,
      isCobol: isCobolPath(p),
    };
    if (info.program && !this.session.maps.has(info.program) && p) {
      const alt = path.basename(p).replace(/\..*$/, '').toUpperCase();
      if (this.session.maps.has(alt)) {
        info.program = alt;
      }
    }
    return info;
  }

  /** Applies the line map and the generated-code mark to a frame. */
  private rewriteFrame(frame: Record<string, unknown>): FrameInfo {
    const info = this.frameInfo(frame);
    if (info.path && info.line !== undefined && this.session.lineMap) {
      const o = this.session.lineMap.originOf(info.path, info.line);
      if (o) {
        frame.source = { ...(frame.source as object), name: path.basename(o.file), path: o.file };
        frame.line = o.line;
        info.path = o.file;
        info.line = o.line;
      }
    }
    if (!info.isCobol) {
      frame.presentationHint = 'subtle';
      if (frame.source) {
        (frame.source as Record<string, unknown>).presentationHint = 'deemphasize';
      }
      const name = String(frame.name ?? '');
      if (!/\((generated C|libcob)\)$/.test(name)) {
        frame.name = `${name} (${info.path ? 'generated C' : 'libcob'})`;
      }
    }
    this.frames.set(info.id, info);
    return info;
  }

  rewriteStack(r: DapResponse): void {
    if (!r.success || !r.body) {
      return;
    }
    const frames = (r.body.stackFrames as Record<string, unknown>[]) ?? [];
    for (const f of frames) {
      this.rewriteFrame(f);
    }
  }

  async topLocation(threadId: number): Promise<FrameInfo | undefined> {
    const r = await this.ch.request('stackTrace', { threadId, startFrame: 0, levels: 1 });
    const frames = r.success ? ((r.body?.stackFrames as Record<string, unknown>[]) ?? []) : [];
    if (!frames.length) {
      return undefined;
    }
    return this.rewriteFrame({ ...frames[0] });
  }

  // ---------------------------------------------------- step per statement
  async onStep(req: DapRequest): Promise<void> {
    const args = (req.arguments ?? {}) as { threadId: number; granularity?: unknown };
    let start: Location | undefined;
    try {
      start = await this.topLocation(args.threadId);
    } catch {
      start = undefined;
    }
    this.stepping = {
      threadId: args.threadId,
      command: req.command === 'stepIn' ? 'stepIn' : 'next',
      granularity: args.granularity,
      start,
      count: 0,
    };
    this.ch.toAdapter(req);
  }

  async continueStepping(ev: DapEvent): Promise<void> {
    const s = this.stepping;
    if (!s) {
      this.ch.send(ev);
      return;
    }
    let loc: FrameInfo | undefined;
    try {
      loc = await this.topLocation(s.threadId);
    } catch {
      loc = undefined;
    }
    const same = loc && s.start && loc.path === s.start.path && loc.line === s.start.line;
    const done = !loc || (loc.isCobol && !same) || s.count >= this.session.maxSteps;
    if (done || this.stepping !== s) {
      if (s.count) {
        this.ch.log(`step: ${s.count} internal steps to ${loc?.path ? path.basename(loc.path) : '?'}:${loc?.line ?? '?'}`);
      }
      this.stepping = undefined;
      this.ch.send(ev);
      return;
    }
    s.count++;
    const cmd = s.command === 'stepIn' && loc?.path ? 'stepIn' : 'next';
    try {
      const r = await this.ch.request(cmd, { threadId: s.threadId, granularity: s.granularity });
      if (!r.success) {
        this.stepping = undefined;
        this.ch.send(ev);
      }
    } catch {
      this.stepping = undefined;
      this.ch.send(ev);
    }
  }

  onScopesResponse(req: DapRequest, r: DapResponse): void {
    const frameId = (req.arguments as { frameId?: number } | undefined)?.frameId;
    if (!r.success || frameId === undefined) {
      return;
    }
    for (const s of (r.body?.scopes as { variablesReference: number }[]) ?? []) {
      this.scopeFrame.set(s.variablesReference, frameId);
    }
  }
}
